/* @jsx h */
import type { Register } from 'claude-code'
import { add, bar, barColor, fmt, isLifetime, shortModel, total, usd, zero, type Lifetime, type Tokens } from './cost.ts'

// hello-mod：Claude Code function hooks 的最小可运行演示。
// 一个 /hello 命令，一条 prompt 上方的面板，面板里有可点的按钮、实时 token/成本计，
// 和一个跑在独立绘制线程上的动画。全部零 token —— 模型不参与其中任何一步。

let open = false
let clicks = 0
let tools = 0
let turns = 0
let lastTool = '—'
let tokens: Tokens = zero()
let model = ''
// $.session.usage() 给的是本会话累计花费，取差值才能累加到跨会话总账上
let lastUsd = 0
let lifetime: Lifetime = { turns: 0, usd: 0, tokens: 0 }

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    // store 读写失败只该损失计数，不该掀翻整个模块：hook 里未捕获的 reject 会卸载模块
    const read = (key: string) => $.store.get(key).catch(err => { $.ui.log(`hello-mod: 读取 ${key} 失败: ${err}`); return undefined })
    const savedClicks = await read('clicks')
    if (typeof savedClicks === 'number') clicks = savedClicks
    const savedLifetime = await read('lifetime')
    if (isLifetime(savedLifetime)) lifetime = savedLifetime
    await $.command.register({
      name: 'hello',
      description: 'function hooks 演示面板：token/成本计 + 可点按钮 (hello-mod)',
      argumentHint: '[off | reset]',
      immediate: true,
    }).catch(err => $.ui.log(`hello-mod: /hello 注册失败: ${err}`))
    return r
  })

  on('command.run', { command: 'hello' }, async ($, e, next) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'off') {
      open = false
      $.ui.invalidate('ui.render')
      return { text: '面板已关闭' }
    }
    if (arg === 'reset') {
      clicks = 0
      lifetime = { turns: 0, usd: 0, tokens: 0 }
      await $.store.set('clicks', 0).catch(() => {})
      await $.store.set('lifetime', lifetime).catch(() => {})
      $.ui.invalidate('ui.render')
      return { text: '点击数和跨会话总账已清零' }
    }
    open = true
    $.ui.invalidate('ui.render')
    return { text: '面板已打开 · 这条回复由插件直接生成，没有经过模型 · /hello off 关闭' }
  })

  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    tools++
    lastTool = e.tool
    if (open) $.ui.invalidate('ui.render')
    return r
  })

  // 一轮结束时结算：e.usage 是这一轮所有响应的 token 计数之和
  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    turns++
    if (e.usage) {
      tokens = add(tokens, e.usage)
      model = e.usage.model
    }
    const session = await $.session.usage().catch(err => { $.ui.log(`hello-mod: 读取用量失败: ${err}`); return undefined })
    const spent = session?.cost?.usd ?? 0
    const delta = Math.max(0, spent - lastUsd)
    lastUsd = spent
    lifetime = {
      turns: lifetime.turns + 1,
      usd: lifetime.usd + delta,
      tokens: lifetime.tokens + (e.usage ? total(add(zero(), e.usage)) : 0),
    }
    await $.store.set('lifetime', lifetime).catch(err => $.ui.log(`hello-mod: 写入总账失败: ${err}`))
    if (open) $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // 只在终端画：桌面端和移动端有自己的一条带子
    if (!open || e.surface !== 'terminal') return next(e)
    const { Box, Button, Client, Text } = await $.ui.resolve(e)
    const session = await $.session.usage().catch(() => undefined)
    const ctx = session?.context
    const percent = ctx?.percent ?? 0
    const spent = session?.cost?.usd ?? lastUsd

    const bump = (n: number) => {
      clicks += n
      $.ui.invalidate('ui.render')
      void $.store.set('clicks', clicks).catch(err => $.ui.log(`hello-mod: 写入失败: ${err}`))
    }
    const close = () => {
      open = false
      $.ui.invalidate('ui.render')
    }

    return (
      <Box flexDirection="column">
        <Text bold color="cyan">hello-mod · function hooks 演示</Text>

        <Box flexDirection="row" columnGap={1}>
          <Text>上下文</Text>
          <Text color={barColor(percent)}>{bar(percent)}</Text>
          <Text>{`${percent}%`}</Text>
          <Text dimColor>{`${fmt(ctx?.tokens ?? 0)} / ${fmt(ctx?.window ?? 0)}`}</Text>
          <Text color="yellow" bold>{`本会话 ${usd(spent)}`}</Text>
          {model ? <Text dimColor>{shortModel(model)}</Text> : null}
        </Box>

        <Text dimColor>
          {`本会话 ${turns} 轮 · in ${fmt(tokens.input)} · out ${fmt(tokens.output)} · 缓存读 ${fmt(tokens.cacheRead)} 写 ${fmt(tokens.cacheWrite)} · 工具 ${tools} 次（最近 ${lastTool}）`}
        </Text>
        <Text dimColor>
          {`跨会话累计 ${lifetime.turns} 轮 · ${usd(lifetime.usd)} · ${fmt(lifetime.tokens)} tokens（存在 $.store）`}
        </Text>

        <Box flexDirection="row" columnGap={1}>
          <Button key="hm:inc" label=" +1 " onPress={() => bump(1)} />
          <Button key="hm:dec" label=" -1 " onPress={() => bump(-1)} />
          <Button key="hm:close" label=" 关闭 " onPress={close} />
          <Text dimColor>{`点击 ${clicks} 次 · 按钮不经过模型`}</Text>
        </Box>

        <Client key="hm:clock" module="./clock.tsx" width={e.viewport?.columns ?? 60} height={1} props={{ percent }} />
        {await next(e)}
      </Box>
    )
  })
}

