// 纯函数：token 累加与格式化。与 Claude Code API 无关，可以单独测试。

export type Tokens = { input: number; output: number; cacheRead: number; cacheWrite: number }
export type Lifetime = { turns: number; usd: number; tokens: number }

export const zero = (): Tokens => ({ input: 0, output: 0, cacheRead: 0, cacheWrite: 0 })

export const add = (t: Tokens, u: { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }): Tokens => ({
  input: t.input + u.input_tokens,
  output: t.output + u.output_tokens,
  cacheRead: t.cacheRead + u.cache_read_input_tokens,
  cacheWrite: t.cacheWrite + u.cache_creation_input_tokens,
})

export const total = (t: Tokens): number => t.input + t.output + t.cacheRead + t.cacheWrite

// 1234 -> 1.2k, 1234567 -> 1.2M
export function fmt(n: number): string {
  if (n < 1000) return String(Math.round(n))
  if (n < 1_000_000) return `${(n / 1000).toFixed(1)}k`
  return `${(n / 1_000_000).toFixed(2)}M`
}

// 很小的金额多给几位小数，否则一直显示 $0.00
export function usd(n: number): string {
  if (n === 0) return '$0'
  if (n < 0.01) return `$${n.toFixed(4)}`
  if (n < 1) return `$${n.toFixed(3)}`
  return `$${n.toFixed(2)}`
}

export function bar(percent: number, width = 10): string {
  const filled = Math.max(0, Math.min(width, Math.round((percent / 100) * width)))
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

export const barColor = (percent: number): string => (percent >= 80 ? 'red' : percent >= 60 ? 'yellow' : 'green')

// 模型 id 通常形如 claude-opus-5-20260101，展示时去掉日期后缀
export const shortModel = (id: string): string => id.replace(/-\d{8}$/, '')

export const isLifetime = (v: unknown): v is Lifetime =>
  typeof v === 'object' && v !== null && typeof (v as Lifetime).turns === 'number' && typeof (v as Lifetime).usd === 'number'

