/* @jsx h */
import type { ClientSurface } from 'claude-code'

// surface module：跑在独立绘制线程上，有自己的帧时钟、键盘和鼠标。
// 注意：这个文件里绝不能出现名为 h 的局部变量 —— 每个 JSX 标签都编译成 h() 调用。
const FRAMES = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']
type State = { tick: number }

export default function Clock(props: { percent?: number } | undefined, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  if (surface.state === undefined) {
    surface.setState({ tick: 0 })
    surface.every(100, () => {
      const s = surface.state
      if (s) surface.setState({ tick: s.tick + 1 })
    })
  }
  const tick = surface.state?.tick ?? 0
  return (
    <Box flexDirection="row" columnGap={1}>
      <Text color="green">{FRAMES[tick % FRAMES.length]}</Text>
      <Text dimColor>{`独立绘制线程 · 第 ${tick} 帧 · 10fps · 零 token · 主线程忙时照转`}</Text>
    </Box>
  )
}

